describe('a user's conversation list over the WebSocket protocol', () => {
  it("answers list_conversations with the connecting user's conversations, newest first, with ISO times", async () => {
    const store = new InMemorySessionStore();
    seed(store);
    const {url} = await startEngineWith(historyOn(store));

    const seen = await answerTo(url, {type: 'list_conversations'});

    expect(seen.map(frame => frame.type)).toEqual(['conversation_list']);
    expect(seen[0]?.conversations).toEqual([
      {sessionId: 'newest', createdAt: expect.stringMatching(ISO), updatedAt: AT.newest, entryCount: 1},
      {sessionId: 'middle', createdAt: expect.stringMatching(ISO), updatedAt: AT.middle, entryCount: 1},
      {sessionId: 'older', createdAt: expect.stringMatching(ISO), updatedAt: AT.older, entryCount: 1},
    ]);
  });

  it('ignores a userId sent in the frame and answers with the connecting user's own list', async () => {
    const store = new InMemorySessionStore();
    seed(store);
    const {url} = await startEngineWith(historyOn(store));

    const seen = await answerTo(url, {type: 'list_conversations', userId: 'u2'});

    expect(seen[0]?.conversations?.map(row => row.sessionId)).toEqual(['newest', 'middle', 'older']);
  });

  it('answers list_conversations with an UNSUPPORTED error and no list when history is not enabled', async () => {
    const store = new InMemorySessionStore();
    seed(store);
    const {url} = await startEngineWith({sessionStore: store});

    const seen = await answerTo(url, {type: 'list_conversations'});

    expect(seen.map(frame => frame.type)).toEqual(['error']);
    expect(seen[0]?.code).toBe('UNSUPPORTED');
  });
});

